# ══════════════════════════════════════════════════════════════════════════
# DEPLOY_1809_ALL.sh — دفعة الكويت اليوم العدد 1809 (الأحد 2026/9/20) كاملةً
# ملف واحد يحلّ محل كل ما سبق تسليمه. النجاح النهائي = DONE_1809_ALL
#
#  (1) مرسوم بقانون 90/2026 في شأن الصكوك الحكومية — 38 كائنًا
#      (ديباجة + 35 مادة في 7 فصول + مذكرة بكتلتين)
#      ⚠ اسم الملف المرفوع قال «80» والنص الرسمي يقول «90»؛ و legis-80-2026 هو
#      قانون تنظيم القضاء — فثمة حارس يوقف الدفعة إن مسّ عددَ كائناته (87).
#
#  (2) مرسوم بقانون 91/2026 بتعديل قانون هيئة أسواق المال 7/2010 — 6 كائنات،
#      وقاعدة التحديث على legis-7-2010: م1 (استبدال تعريفين) + 7 مواد تُوسم ملغاة
#      (108-113 و116) ونصوصها باقية كاملة.
#
#  (3) مرسوم بقانون 93/2026 بتعديل م11 من نظام مكافحة الغش التجاري — 3 كائنات
#      (مادتاه + مذكرته)، وقاعدة التحديث على legis-20-2019-m11 بنصها النافذ.
#
#  (4) ترقية اللائحة التنفيذية لقانون التوثيق (regl-10-2020، 67 كائنًا) من نسخة
#      مسودة بلا رقم إلى النص الرسمي: قرار وزير العدل رقم (590) لسنة 2026.
#      ⚠ حارس: legis-10-2020 (قانون التوثيق نفسه) لا يُمس — تُقاس بصمة نصوصه.
#
#  ثم فهرسة تفاضلية واحدة (لا فهرسة كاملة أبدًا)، واتساق العدّادين، واختبارات
#  استرجاع حية، وبطارية 13/13.
#
#  كل الكتابات داخل معاملات، والنصوص المستبدَلة كلها إلى previous_versions[]،
#  وإعادة تشغيل الملف آمنة بلا تكرار.
# ══════════════════════════════════════════════════════════════════════════
set -euo pipefail

# لا يُعتمد على $0 أبدًا: عند اللصق في الطرفية يكون $0 هو «bash» لا مسار ملف، فينهار
# cp/chmod ويقتل `set -e` الجلسة (وهو ما حدث فعلًا). البديل: BASH_SOURCE — فإن كان
# السكربت ملفًا حقيقيًا شُغِّل في الخلفية الصامدة، وإن كان ملصوقًا استمر في الواجهة.
SELF="${BASH_SOURCE[0]:-}"
if [ "${1:-}" != "--worker" ] && [ -n "$SELF" ] && [ -f "$SELF" ]; then
  LOG=/tmp/deploy_1809_all_$(date +%s).log
  echo "running in background (survives terminal disconnect). log: $LOG"
  nohup bash "$SELF" --worker > "$LOG" 2>&1 &
  disown
  echo "follow with:  tail -f $LOG"
  exit 0
fi
[ "${1:-}" = "--worker" ] || echo "(pasted mode: running in the foreground)"

cd /opt/LegalMind
set -a; . /opt/LegalMind/deploy/.env; set +a
mkdir -p /opt/LegalMind/tools /opt/legalmind-data

